  transition: all var(--transition);
  white-space: nowrap;
}
.tab-btn:hover { color: var(--white); background: rgba(0,180,216,0.06); }
.tab-btn.active { background: var(--teal-dark); color: var(--white); }

.tab-panel { display: none; animation: fadeIn 300ms ease; }
.tab-panel.active { display: block; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ── ACCORDION ── */
.accordion-item {
  border: 1px solid rgba(0,180,216,0.1);
  border-radius: var(--radius-lg);
  margin-bottom: 12px;
  overflow: hidden;
  transition: border-color var(--transition);
}
.accordion-item:hover { border-color: rgba(0,180,216,0.2); }

.accordion-header {
  width: 100%;
  padding: 20px 24px;
  background: var(--navy-mid);
  border: none;
  color: var(--white);
  font-family: var(--font);
  font-size: 17px; font-weight: 600;
  text-align: left;
  cursor: pointer;
  display: flex; align-items: center; justify-content: space-between;
  transition: background var(--transition);
}
.accordion-header:hover { background: var(--navy-light); }

.accordion-icon {
  width: 20px; height: 20px;
  position: relative;
  flex-shrink: 0;
}
.accordion-icon::before, .accordion-icon::after {
  content: ''; position: absolute;
  background: var(--teal);
  transition: transform var(--transition);
}
.accordion-icon::before { width: 20px; height: 2px; top: 9px; left: 0; }
.accordion-icon::after { width: 2px; height: 20px; top: 0; left: 9px; }

.accordion-item.active .accordion-icon::after { transform: rotate(90deg); }

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease;
}
.accordion-content {
  padding: 0 24px 24px;
  color: var(--gray-300);
  font-size: 15px;
  line-height: 1.7;
}

/* ── FORMS ── */
.form-group { margin-bottom: 20px; }
.form-label {
  display: block; margin-bottom: 6px;
  font-size: 14px; font-weight: 500; color: var(--gray-200);
}
.form-label .required { color: var(--teal); }

.form-input {
  width: 100%;
  padding: 12px 16px;
  background: var(--navy-light);
  border: 1px solid rgba(0,180,216,0.15);
  border-radius: var(--radius);
  color: var(--white);
  font-family: var(--font);
  font-size: 15px;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.form-input::placeholder { color: var(--gray-400); }
.form-input:focus {
  outline: none;
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(0,180,216,0.15);
}
.form-input.error { border-color: var(--danger); }
.form-error {
  font-size: 13px; color: var(--danger);
  margin-top: 4px; display: none;
}
.form-input.error + .form-error { display: block; }

textarea.form-input { resize: vertical; min-height: 120px; }

/* ── STAT CIRCLES ── */
.stat-circle {
  width: 160px; height: 160px;
  border-radius: 50%;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  position: relative;
}
.stat-circle::before {
  content: '';
  position: absolute; inset: 0;
  border-radius: 50%;
  border: 3px solid rgba(0,180,216,0.15);
}
.stat-circle::after {
  content: '';
  position: absolute; inset: 0;
  border-radius: 50%;
  border: 3px solid var(--teal);
  clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%);
}
.stat-value { font-size: 36px; font-weight: 800; color: var(--teal); }
.stat-label { font-size: 13px; color: var(--gray-300); text-align: center; max-width: 120px; }

/* ── PROGRESS BAR ── */
.progress-bar {
  height: 8px;
  background: var(--navy-light);
  border-radius: 4px;
  overflow: hidden;
  margin-top: 12px;
}
.progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--teal-dark), var(--teal));
  border-radius: 4px;
  transition: width 1s ease;
}

/* ── TESTIMONIAL CAROUSEL ── */
.carousel { position: relative; overflow: hidden; }
.carousel-track { display: flex; transition: transform 400ms ease; }
.carousel-slide { min-width: 100%; padding: 0 4px; }

.carousel-dots {
  display: flex; justify-content: center; gap: 8px; margin-top: 32px;
}
.carousel-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--navy-lighter);
  border: none;
  cursor: pointer;
  transition: background var(--transition);
}
.carousel-dot.active { background: var(--teal); }

.testimonial-card {
  background: var(--navy-mid);
  border: 1px solid rgba(0,180,216,0.1);
  border-radius: var(--radius-xl);
  padding: 40px;
  position: relative;
}
.testimonial-quote {
  font-size: 18px; color: var(--gray-100);
  line-height: 1.8; font-style: italic;
  margin-bottom: 24px;
}
.testimonial-quote::before {
  content: '\201C';
  font-size: 64px; color: var(--teal-dark);
  position: absolute; top: 16px; left: 24px;
  line-height: 1; opacity: 0.5;
}
.testimonial-author { font-size: 14px; color: var(--teal); font-weight: 600; }

/* ── DIAGRAM ── */
.diagram-container {
  background: var(--navy-mid);
  border: 1px solid rgba(0,180,216,0.12);
  border-radius: var(--radius-xl);
  padding: 48px;
  position: relative;
}

.diagram-node {
  background: var(--navy-deep);
  border: 2px solid rgba(0,180,216,0.2);
  border-radius: var(--radius-lg);
  padding: 24px;
  text-align: center;
  transition: all var(--transition);
}
.diagram-node:hover {
  border-color: var(--teal);
  box-shadow: 0 0 24px rgba(0,180,216,0.15);
}
.diagram-node-title {
  font-size: 15px; font-weight: 700;
  color: var(--white); margin-top: 12px;
}
.diagram-node-desc {
  font-size: 13px; color: var(--gray-300); margin-top: 6px;
}

/* ── FOOTER ── */
.footer {
  background: var(--navy-mid);
  border-top: 1px solid rgba(0,180,216,0.08);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand { font-size: 22px; font-weight: 800; color: var(--white); margin-bottom: 16px; }
.footer-brand span { color: var(--teal); }
.footer-desc { font-size: 14px; color: var(--gray-400); line-height: 1.7; max-width: 320px; }

.footer-heading {
  font-size: 13px; font-weight: 700; letter-spacing: 2px;
  color: var(--teal); text-transform: uppercase; margin-bottom: 20px;
}
.footer-links { list-style: none; }
.footer-links li { margin-bottom: 10px; }
.footer-links a { color: var(--gray-300); font-size: 14px; }
.footer-links a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(0,180,216,0.08);
  padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center;
  font-size: 13px; color: var(--gray-400);
}

/* ── COOKIE BANNER ── */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0;
  background: var(--navy-mid);
  border-top: 1px solid rgba(0,180,216,0.15);
  padding: 20px 24px;
  z-index: 1001;
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  transform: translateY(0);
  transition: transform 400ms ease;
  box-shadow: 0 -4px 24px rgba(0,0,0,0.3);
}
.cookie-banner.hidden { transform: translateY(100%); pointer-events: none; }
.cookie-text { font-size: 14px; color: var(--gray-200); max-width: 720px; }
.cookie-buttons { display: flex; gap: 12px; flex-shrink: 0; }

/* ── HERO ── */
.hero {
  padding: 160px 0 96px;
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 30% 20%, rgba(0,119,182,0.12) 0%, transparent 60%),
              radial-gradient(ellipse at 70% 80%, rgba(0,180,216,0.06) 0%, transparent 50%);
  pointer-events: none;
}
.hero-content { position: relative; z-index: 1; }

.hero-title {
  font-size: 52px; font-weight: 900; color: var(--white);
  line-height: 1.1; letter-spacing: -1px;
  margin-bottom: 24px; max-width: 720px;
}
.hero-subtitle {
  font-size: 20px; color: var(--gray-300);
  line-height: 1.7; max-width: 600px; margin-bottom: 40px;
}
.hero-actions { display: flex; gap: 16px; flex-wrap: wrap; }

/* ── SVG ICON HELPERS ── */
.icon-sm { width: 20px; height: 20px; }
.icon-md { width: 24px; height: 24px; }
.icon-lg { width: 32px; height: 32px; }
.icon-xl { width: 48px; height: 48px; }

/* ── UTILITIES ── */
.text-center { text-align: center; }
.text-teal { color: var(--teal); }
.mb-0 { margin-bottom: 0; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.mb-32 { margin-bottom: 32px; }
.mb-48 { margin-bottom: 48px; }
.mb-64 { margin-bottom: 64px; }
.mx-auto { margin-left: auto; margin-right: auto; }
.grid-2 { display: grid; grid-template-columns: repeat(2,1fr); gap: 24px; }
.grid-3 { display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; }

/* ── FEATURE BANNER ── */
.featured-banner {
  background: linear-gradient(135deg, var(--teal-dark), #005f8a);
  border-radius: var(--radius-xl);
  padding: 48px;
  display: flex; align-items: center; justify-content: space-between;
  gap: 32px; position: relative; overflow: hidden;
}
.featured-banner::after {
  content: '';
  position: absolute; right: -40px; top: -40px;
  width: 200px; height: 200px;
  background: rgba(255,255,255,0.05);
  border-radius: 50%;
}

/* ── RESPONSIVE ── */
@media (max-width: 1024px) {
  .hero-title { font-size: 42px; }
  .section-title { font-size: 32px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .grid-3 { grid-template-columns: repeat(2,1fr); }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
    position: absolute; top: 72px; left: 0; right: 0;
    background: var(--navy-mid);
    flex-direction: column; gap: 0;
    padding: 16px 0;
    border-bottom: 1px solid rgba(0,180,216,0.1);
  }
  .nav-links.open { display: flex; }
  .nav-links li { width: 100%; }
  .nav-links a { display: block; padding: 12px 24px; }
  .nav-hamburger { display: flex; }
  .dropdown-menu {
    position: static; opacity: 1; visibility: visible;
    transform: none; background: rgba(0,0,0,0.15);
    box-shadow: none; border: none;
  }
  .nav-dropdown > a::after { display: none; }

  .hero { padding: 120px 0 64px; }
  .hero-title { font-size: 32px; }
  .hero-subtitle { font-size: 17px; }
  .section { padding: 64px 0; }
  .section-title { font-size: 28px; }

  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }

  .featured-banner { flex-direction: column; text-align: center; padding: 32px; }
  .diagram-container { padding: 24px; }

  .cookie-banner { flex-direction: column; text-align: center; }

  .tabs-nav { flex-wrap: nowrap; justify-content: flex-start; }
  .tab-btn { padding: 10px 16px; font-size: 13px; }
}

@media (max-width: 480px) {
  .hero-title { font-size: 28px; }
  .hero-actions { flex-direction: column; }
  .btn { width: 100%; }
  .stat-circle { width: 130px; height: 130px; }
  .stat-value { font-size: 28px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

