function validateField(field) {
  var isValid = true;

  if (field.required && !field.value.trim()) {
    isValid = false;
  }

  if (field.type === 'email' && field.value.trim()) {
    var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(field.value.trim())) isValid = false;
  }

